mapper.select:
SELECT RR.id, RR.report_code, RR.report_name, RR.report_type, RR.template_id, RT.template_name, RR.status, RR.publish_time, RR.remark, RR.create_by, COALESCE(NULLIF(SUA.nick_name, ''), SUA.user_name) AS create_name, RR.create_time, RR.update_by, COALESCE(NULLIF(SUB.nick_name, ''), SUB.user_name) AS update_name, RR.update_time FROM rpt_report RR LEFT JOIN rpt_template RT ON RR.template_id = RT.id LEFT JOIN sys_account SUA ON RR.create_by = SUA.user_name LEFT JOIN sys_account SUB ON RR.update_by = SUB.user_name
AND RR.report_name LIKE #{reportName}
AND RR.report_code LIKE #{reportCode}
AND RR.status = #{report.status}
ORDER BY RR.create_time DESC
